-- KETIC pilot — initial schema + seed data
-- Run this in the Supabase SQL editor.

-- Enable UUID generation
create extension if not exists "pgcrypto";

-- Properties
create table properties (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  name text not null,
  location text not null,
  room_count integer not null,
  pms_type text not null default 'cloudbeds',
  api_key text,
  last_synced_at timestamptz,
  created_at timestamptz default now()
);

create index idx_properties_slug on properties(slug);

-- Room events (one row per detected vacancy window)
create table room_events (
  id uuid primary key default gen_random_uuid(),
  property_id uuid references properties(id) on delete cascade,
  room_number text not null,
  room_type text,
  floor integer,
  checkout_time timestamptz not null,
  next_checkin_time timestamptz,
  vacancy_hours numeric(6,2) not null,
  kwh_wasted numeric(8,2) not null,
  cost_wasted numeric(8,2) not null,
  ketic_would_save numeric(8,2) not null,
  event_date date not null,
  created_at timestamptz default now(),
  unique(property_id, room_number, checkout_time)
);

create index idx_room_events_property_date on room_events(property_id, event_date desc);
create index idx_room_events_property_cost on room_events(property_id, cost_wasted desc);

-- Seed: property
with new_property as (
  values ('the-meridian-austin', 'The Meridian', 'Austin, TX', 180, 'cloudbeds')
  returning id
)
